import { g } from '../runtime/scope.ts';

const code = "g.$ = (id) => document.getElementById(id);\ng.esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');\ng.fmt = (n) => n.toLocaleString('ko-KR');\ng.gcdInt = function gcdInt(a, b) {\n  a = Math.abs(a | 0); b = Math.abs(b | 0);\n  while (b) { const t = a % b; a = b; b = t; }\n  return a || 1;\n}\n/** 배수를 정수·분수·역수로. 소수는 내지 않고 나누기/분수로 넘긴다. */\ng.multView = function multView(m) {\n  const x = Number(m);\n  if (!Number.isFinite(x)) return { op: '×', kind: 'int', text: '0' };\n  const sign = x < 0 ? -1 : 1;\n  const ax = Math.abs(x);\n  let bestP = Math.round(ax), bestQ = 1, bestErr = Math.abs(ax - bestP);\n  for (let q = 2; q <= 64; q++) {\n    const p = Math.round(ax * q);\n    const err = Math.abs(ax - p / q);\n    if (err < bestErr - 1e-12) { bestP = p; bestQ = q; bestErr = err; }\n    if (err < 1e-10) break;\n  }\n  const g = gcdInt(bestP, bestQ);\n  const p = sign * (bestP / g);\n  const q = bestQ / g;\n  if (q === 1) return { op: '×', kind: 'int', text: String(p) };\n  if (p === 1) return { op: '÷', kind: 'div', text: String(q) };\n  if (p === -1) return { op: '÷', kind: 'div', text: '-' + q };\n  return { op: '×', kind: 'frac', text: p + '/' + q };\n}\ng.fmtMult = (m) => multView(m).text;\ng.fmtMultLabel = (m) => {\n  const v = multView(m);\n  return v.op + v.text;\n};\ng.applyMultEl = function applyMultEl(el, m, timesEl) {\n  if (!el) return;\n  const v = multView(m);\n  el.classList.toggle('is-div', v.kind !== 'int');\n  if (v.kind === 'int') el.textContent = v.text;\n  else el.innerHTML = `<span class=\"mult-div\">${esc(v.text)}</span>`;\n  if (timesEl) {\n    timesEl.textContent = v.op;\n    timesEl.classList.toggle('is-div', v.kind !== 'int');\n  }\n}\n\ng.TTI_LABEL = { hongdan: '홍단', cheongdan: '청단', chodan: '초단', bi_tti: '비단' };\n\ng.auraCardCls = function auraCardCls(opts, uid) {\n  if (!opts.selectable || !opts.auraUids || !opts.auraUids.has(uid)) return '';\n  return opts.auraKind === 'junk' ? ' coach-aura-junk' : ' coach-aura';\n}\n\n/** 종류별 하단 서예 오버레이 — 광 상시 / 열끗 옵션 / 쌍피·띠·피는 없음 */\ng.CARD_OVERLAY = {\n  kwang: 'Assets/Overlay/overlay_gwang.webp?v=12',\n  yeol: 'Assets/Overlay/overlay_yeolkkeut.webp?v=12',\n};\n\n/** 내기/버리기 버튼 — 시안 D: 라벨 + 남은 횟수 점만 */\ng.actionBtnHTML = function actionBtnHTML(label, left) {\n  const n = Math.max(0, Math.min(Math.floor(left) || 0, 12));\n  const pips = n ? '<i></i>'.repeat(n) : '';\n  return `<span class=\"abtn-label\">${label}</span><span class=\"act-pips\" aria-hidden=\"true\">${pips}</span>`;\n}\n\ng.syncActionBtn = function syncActionBtn(btn, label, left) {\n  const want = Math.max(0, Math.min(Math.floor(left) || 0, 12));\n  let labelEl = btn.querySelector('.abtn-label');\n  let pipsEl = btn.querySelector('.act-pips');\n  if (!labelEl || !pipsEl) {\n    btn.innerHTML = actionBtnHTML(label, want);\n    return;\n  }\n  labelEl.textContent = label;\n  const live = [...pipsEl.querySelectorAll('i:not(.pip-out)')];\n  const have = live.length;\n  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  if (want > have) {\n    for (let i = have; i < want; i++) {\n      const pip = document.createElement('i');\n      if (!reduceMotion) pip.className = 'pip-in';\n      pipsEl.appendChild(pip);\n    }\n  } else if (want < have) {\n    const remove = live.slice(want);\n    for (const pip of remove) {\n      if (reduceMotion) {\n        pip.remove();\n        continue;\n      }\n      pip.classList.remove('pip-in');\n      pip.classList.add('pip-out');\n      const done = () => { if (pip.parentNode) pip.remove(); };\n      pip.addEventListener('animationend', done, { once: true });\n      setTimeout(done, 320);\n    }\n  }\n}\n\n/**\n * 카드 한 장의 표현을 세 갈래로 나눈다:\n *   cls   — 상태(선택·오라·이달 등)마다 바뀜 → 재사용 시 className만 교체\n *   inner — 카드 자체(그림·달·태그)에만 의존 → csig가 같으면 그대로 둔다\n *   csig  — inner를 다시 만들어야 하는지 판별하는 서명\n * 손패는 이 분리를 이용해 <img>를 살려두므로 선택할 때 그림이 다시 로드되지 않는다.\n */\ng.cardVisual = function cardVisual(card, opts = {}) {\n  const discarding = !!(state.discardAnimUids && state.discardAnimUids.includes(card.uid));\n  const dd = discarding ? state.discardAnimUids.indexOf(card.uid) : -1;\n  const dealIdx = state.dealInUids ? state.dealInUids.indexOf(card.uid) : -1;\n  const selectable = !!opts.selectable && !discarding;\n  const vars = {};\n  if (dealIdx >= 0) vars['--di'] = String(dealIdx);\n  if (discarding) vars['--dd'] = String(dd);\n  const flags =\n    (selectable && state.selected.includes(card.uid) ? ' sel' : '') +\n    (dealIdx >= 0 ? ' deal-in' : '') +\n    (discarding ? ' discarding' : '') +\n    auraCardCls(opts, card.uid) +\n    (selectable ? '' : ' static');\n  const faceDown = card.faceDown && !opts.reveal;\n  const csig = `${locale}|${faceDown ? 'd' : 'u'}|${card.type}|${card.month}|${(card.tags || []).join('.')}|${card.art || ''}`;\n\n  if (faceDown) {\n    return { cls: `card facedown${flags}`, inner: '<div class=\"back-q\">?</div>', vars, click: selectable, csig };\n  }\n  const base = cardFaceParts(card, opts);\n  return { cls: `${base.cls}${flags}`, inner: base.inner, vars, click: selectable, csig };\n}\n\ng.cardHTML = function cardHTML(card, opts = {}) {\n  const v = cardVisual(card, opts);\n  const varBits = Object.entries(v.vars).map(([k, val]) => `${k}:${val}`);\n  const styleAttr = varBits.length ? ` style=\"${varBits.join(';')}\"` : '';\n  const click = v.click ? ` onclick=\"toggleSelect(${card.uid})\"` : '';\n  return `<div class=\"${v.cls}\" data-uid=\"${card.uid}\" data-csig=\"${esc(v.csig)}\"${styleAttr}${click}>${v.inner}</div>`;\n}\n\ng.cardFaceParts = function cardFaceParts(card, opts) {\n  let cls = `card ${card.type}`;\n  let body = '', tag = '', tagOpt = false;\n  if (card.type === 'kwang') {\n    if (card.tags.includes('bikwang')) cls += ' rain';\n    tag = uiCardTag(card);\n  } else if (card.type === 'yeol') {\n    tag = uiCardTag(card);\n    tagOpt = true;\n  } else if (card.type === 'tti') {\n    const color = card.tags.find((x) => TTI_LABEL[x]) || 'bi_tti';\n    cls += ' ' + color;\n    tag = uiTtiLabel(color);\n  } else if (card.type === 'ssangpi') {\n    tag = uiCardTag(card);\n  } else {\n    tag = uiCardTag(card);\n  }\n  const overlaySrc = CARD_OVERLAY[card.type];\n  const overlayOpt = card.type === 'yeol';\n  if (card.art) {\n    cls += ' has-art';\n    body = `<img class=\"face-img\" src=\"${esc(assetSrc(card.art))}\" alt=\"${esc(uiMonthName(card.month))} ${esc(tag)}\" draggable=\"false\">`;\n    if (overlaySrc) {\n      const ovCls = overlayOpt ? 'face-overlay overlay-opt' : 'face-overlay';\n      body += `<img class=\"${ovCls}\" src=\"${esc(assetSrc(overlaySrc))}\" alt=\"\" draggable=\"false\">`;\n    }\n  } else if (card.type === 'kwang') {\n    // 이미지 폴백 — 이모지 대신 글자. 48장 전부 art가 있어 평소엔 안 탄다.\n    body = `<div class=\"gwangmark\">光</div>`;\n  } else if (card.type === 'yeol') {\n    body = `<div class=\"art art-text\">${esc(uiMonthName(card.month))}</div>`;\n  } else if (card.type === 'tti') {\n    const color = card.tags.find((x) => TTI_LABEL[x]) || 'bi_tti';\n    body = `<div class=\"ribbon\">${color === 'chodan' ? '' : uiTtiLabel(color)}</div>`;\n  } else {\n    body = `<div class=\"art art-text\">${hanjaMonth(card.month)}</div>`;\n  }\n  if (!opts.noSeason && card.month === state.round) cls += ' season'; // 이달의 패 강조\n  const monthLabel = card.art\n    ? `<div class=\"month-badge\">${hanjaMonth(card.month)}</div>`\n    : `<div class=\"month\">${hanjaMonth(card.month)}</div><div class=\"mname\">${uiMonthName(card.month)}</div>`;\n  // 이모지 폴백: 광 상시 / 열끗 옵션 / 띠·피·쌍피는 그림(+쌍피 점)\n  const showTag = !card.art && (card.type === 'kwang' || tagOpt);\n  const tagHtml = showTag\n    ? `<div class=\"tag${tagOpt ? ' tag-opt' : ''}\">${tag}</div>`\n    : '';\n  const ssangPips = card.type === 'ssangpi'\n    ? `<div class=\"ssang-pips\" aria-hidden=\"true\"><i></i><i></i></div>`\n    : '';\n  return { cls, inner: `${monthLabel}${body}${ssangPips}${tagHtml}` };\n}\n\ng.CARD_STATE_VARS = ['--di', '--dd'];\ng.syncElClass = function syncElClass(el, cls) {\n  const want = cls.trim().split(/\\s+/).filter(Boolean);\n  const have = el.className.trim().split(/\\s+/).filter(Boolean);\n  if (want.length === have.length && want.every((c) => el.classList.contains(c))) return;\n  for (const c of have) if (!want.includes(c)) el.classList.remove(c);\n  for (const c of want) if (!el.classList.contains(c)) el.classList.add(c);\n}\ng.applyCardVars = function applyCardVars(el, vars) {\n  for (const k of CARD_STATE_VARS) {\n    const want = vars[k];\n    if (want != null) {\n      if (el.style.getPropertyValue(k) !== want) el.style.setProperty(k, want);\n    } else if (el.style.getPropertyValue(k)) {\n      el.style.removeProperty(k);\n    }\n  }\n}\n\n/**\n * 손패 렌더 — innerHTML로 통째로 갈아끼우지 않고 uid로 짝지어 재사용한다.\n * <img>가 살아 있으니 카드를 고를 때 흰 카드가 번쩍이지 않는다.\n */\ng.renderHandArea = function renderHandArea(opts) {\n  const host = $('handarea');\n  if (!host) return;\n  const spare = new Map();\n  for (const el of [...host.children]) {\n    if (el.dataset && el.dataset.uid != null) spare.set(el.dataset.uid, el);\n    else el.remove();\n  }\n  const wanted = [];\n  for (const card of state.hand) {\n    const v = cardVisual(card, opts);\n    const key = String(card.uid);\n    let el = spare.get(key);\n    if (el && el.dataset.csig !== v.csig) el = null; // 앞뒤가 뒤집혔거나 언어가 바뀜 → 다시 만든다\n    if (el) {\n      spare.delete(key);\n      syncElClass(el, v.cls);\n    } else {\n      el = document.createElement('div');\n      el.className = v.cls;\n      el.dataset.uid = key;\n      el.dataset.csig = v.csig;\n      el.innerHTML = v.inner;\n    }\n    applyCardVars(el, v.vars);\n    el.onclick = v.click ? () => toggleSelect(card.uid) : null;\n    wanted.push(el);\n  }\n  for (const el of spare.values()) el.remove();\n  let node = host.firstChild;\n  for (const el of wanted) {\n    if (node === el) { node = el.nextSibling; continue; }\n    host.insertBefore(el, node);\n  }\n}\n\ng.render = function render() {\n  document.body.dataset.screen = state.screen || '';\n  document.body.classList.toggle('night-round', isNight());\n  document.body.classList.toggle('dark-shop', state.screen === 'shop' && !!state.darkShop);\n  renderTopbar();\n  renderSide();\n  renderTable();\n  renderChunhyang();\n  renderModal();\n  renderSurvey();\n  renderShortcutPrompt();\n  renderCoach();\n}\n\ng.renderChunhyang = function renderChunhyang() {\n  const root = $('chunhyang');\n  if (!CHUNHYANG_ENABLED) {\n    if (root) root.style.display = 'none';\n    return;\n  }\n  if (root) root.style.display = '';\n  const hint = chunhyangHint();\n  const face = $('ch-face');\n  const bubble = $('ch-bubble');\n  const tabs = $('ch-hint-tabs');\n  const touchUI = isTouchUI();\n  const canTouchHint = touchUI && state.drunk && state.screen === 'play' && state.selected.length >= 1;\n  const selPredict = canTouchHint\n    ? chunhyangHoverPredict(state.touchHintMode || 'play')\n    : null;\n\n  if (tabs) {\n    if (canTouchHint) {\n      tabs.hidden = false;\n      tabs.querySelectorAll('button').forEach((b) => {\n        b.classList.toggle('on', b.dataset.hint === (state.touchHintMode || 'play'));\n      });\n    } else {\n      tabs.hidden = true;\n    }\n  }\n\n  if (state.tempReact && Date.now() < state.tempReact.expires) {\n    face.textContent = state.tempReact.mood;\n    bubble.textContent = state.tempReact.text;\n  } else if (state.hoverReact) {\n    face.textContent = state.hoverReact.mood;\n    bubble.textContent = state.hoverReact.text;\n  } else if (selPredict) {\n    const tag = state.touchHintMode === 'discard' ? '버리기' : '내기';\n    face.textContent = selPredict.mood;\n    bubble.textContent = `[${tag}] ${selPredict.text}`;\n  } else if (hint) {\n    face.textContent = hint.mood;\n    bubble.textContent = hint.text;\n  } else if (state.drunk) {\n    face.textContent = '😊';\n    bubble.textContent = touchUI\n      ? '패를 고르면 감이 와요. 버튼 길게 누르거나 아래 탭으로 내기/버리기 감을 바꿔요.'\n      : '이번 달 훈수 중이에요. 패 고르고 버튼에 올려보세요~';\n  } else if (state.screen === 'prep' || state.screen === 'shop') {\n    face.textContent = state.chunhyangNext ? '😄' : '😴';\n    bubble.textContent = state.chunhyangNext\n      ? '다음 달 훈수 예약됐어요! 잘 부탁드려요~'\n      : '다음 달 훈수는 3냥이에요. 시작 전에 예약해 주세요.';\n  } else {\n    face.textContent = '😴';\n    bubble.textContent = touchUI ? '' : '이번 달은 훈수 없어요… (주막에서 다음 달 예약)';\n  }\n  const btn = $('ch-btn');\n  if (state.screen === 'prep' || state.screen === 'shop') {\n    btn.style.display = '';\n    if (state.chunhyangNext) {\n      btn.textContent = '✓ 다음 달 훈수 예약됨';\n      btn.disabled = true;\n    } else {\n      btn.textContent = `다음 달 훈수 예약 (3냥)`;\n      btn.disabled = state.money < 3;\n    }\n  } else if (state.drunk) {\n    btn.style.display = '';\n    btn.textContent = `${state.round}월 훈수 중`;\n    btn.disabled = true;\n  } else {\n    btn.style.display = '';\n    btn.textContent = '훈수 없음';\n    btn.disabled = true;\n  }\n}\n\ng.renderTopbar = function renderTopbar() {\n  const open = openJokerSlots();\n  let slots = '';\n  for (let i = 0; i < JOKER_SLOT_MAX; i++) {\n    const j = state.jokers[i];\n    if (j) {\n      const def = JOKER_BY_ID[j.id];\n      const uj = uiJoker(def);\n      const tap = isTouchUI() ? ` onclick=\"showJokerPop(${i})\" role=\"button\"` : '';\n      const gain = formatJokerGain(def.id);\n      const gainEmpty = gain === t('gainNone') ? ' empty' : '';\n      slots += `<div class=\"jokerslot filled aura-${def.rarity}\" data-jid=\"${esc(def.id)}\" tabindex=\"0\"${tap}>\n        <div class=\"jname\">${esc(jokerDisplayName(j))}</div>\n        ${uj.kind ? `<div class=\"jkind\">${esc(uj.kind)}</div>` : ''}\n        <div class=\"jtip\">${esc(uj.desc)}${jokerLiveNote(def.id) ? `<br>${esc(jokerLiveNote(def.id).trim())}` : ''}<div class=\"jtip-gain${gainEmpty}\">${esc(gain)}</div></div>\n      </div>`;\n    } else if (i < open) {\n      slots += `<div class=\"jokerslot\">${t('emptyJoker')}</div>`;\n    } else {\n      slots += `<div class=\"jokerslot locked\">${lockedSlotLabel(i + 1)}</div>`;\n    }\n  }\n  $('jokerbar').innerHTML = slots;\n  $('moneybox').textContent = t('nyang')(state.money);\n}\n\ng.showJokerPop = function showJokerPop(idx) {\n  if (!isTouchUI()) return;\n  const j = state.jokers[idx];\n  if (!j) return;\n  const def = JOKER_BY_ID[j.id];\n  const uj = uiJoker(def);\n  $('joker-pop-icon').textContent = def.icon;\n  $('joker-pop-name').textContent = jokerDisplayName(j);\n  $('joker-pop-meta').innerHTML = `\n    <span class=\"o-rarity r-${def.rarity}\">${uiRarity(def.rarity)}</span>\n    <span class=\"o-kind\">${esc(uj.kind || '')}</span>`;\n  $('joker-pop-desc').textContent = uj.desc + jokerLiveNote(def.id);\n  const gain = formatJokerGain(def.id);\n  const gainEl = $('joker-pop-gain');\n  gainEl.textContent = gain;\n  gainEl.classList.toggle('empty', gain === t('gainNone'));\n  $('joker-pop-overlay').classList.add('show');\n  const jc = $('joker-pop-close'); if (jc) jc.textContent = tu('close');\n}\n\ng.closeJokerPop = function closeJokerPop() {\n  $('joker-pop-overlay').classList.remove('show');\n}\n\ng.setNeedVal = function setNeedVal(score) {\n  const el = $('need-val');\n  if (!el) return;\n  const need = Math.max(0, state.target - score);\n  el.textContent = need === 0 ? t('achieved') : fmt(need);\n  el.classList.toggle('done', need === 0);\n}\n\ng.renderSide = function renderSide() {\n  const bossTag = isBossRound(state.round) ? ` <span class=\"bak\">${t('bak')}</span>` : '';\n  const M = MONTHS[state.round - 1];\n  const night = isNight();\n  const rp = $('roundpanel');\n  if (rp) {\n    rp.classList.toggle('day', !night);\n    rp.classList.toggle('night', night);\n  }\n  $('roundlabel').innerHTML = `${hanjaMonth(state.round)} · ${uiMonthName(state.round)}` +\n    ` <span class=\"round-meta\">${t('roundMeta')(state.round, ROUNDS)}</span>${bossTag}`;\n  $('seasonline').innerHTML = (night ? t('seasonLineNight') : t('seasonLineDay'))(hanjaMonth(state.round));\n\n  const bb = $('bossbanner');\n  if (state.boss) {\n    const b = uiBoss(BOSS_BY_ID[state.boss]);\n    const nullified = hasJoker('pibak_boheom') && MILD_BOSSES.includes(state.boss);\n    bb.style.display = 'block';\n    bb.innerHTML = `<b>${esc(b.name)}</b> — ${esc(b.desc)}${nullified ? ` <span class=\"nullified\">${t('bossNull')}</span>` : ''}`;\n  } else bb.style.display = 'none';\n\n  $('target-val').textContent = fmt(state.target);\n  // 연출 중엔 사이드 점수를 연출 시작값으로 두고, juice가 DOM을 직접 롤업\n  const displayScore = (state.juicing && state.lastPlay)\n    ? state.lastPlay.scoreBefore\n    : state.roundScore;\n  $('score-val').textContent = fmt(displayScore);\n  setNeedVal(displayScore);\n  $('gauge-fill').style.width = Math.min(100, (displayScore / state.target) * 100) + '%';\n  $('gauge-fill').classList.remove('overflow');\n  $('gauge').classList.remove('overflow');\n\n  const gl = $('golevel');\n  if (state.goLevel > 0) {\n    gl.style.display = 'block';\n    gl.textContent = t('goLevel')(state.goLevel, fmtMult(goMult(state.goLevel)), goBonus(state.goLevel, state.round));\n  } else gl.style.display = 'none';\n\n  renderPreview();\n\n  $('deck-val').textContent = `${state.deck.length}`;\n  const deckLow = state.deck.length > 0 && state.deck.length <= 5;\n  const deckbox = $('deckbox');\n  deckbox.classList.toggle('deck-low', deckLow);\n  deckbox.classList.remove('deck-blocked');\n  deckbox.setAttribute('aria-disabled', 'false');\n  deckbox.tabIndex = 0;\n  deckbox.title = deckLow ? t('deckLow')(state.deck.length) : t('deckTitle');\n\n  const lp = $('playlog-panel');\n  if (playLogVisible && state.playLog.length > 0) {\n    lp.style.display = 'block';\n    $('playlog').innerHTML = state.playLog\n      .map((p, i) => `<div><span><span class=\"lognum\">${i + 1}.</span> ${esc(p.hand)}</span><b>${fmt(p.score)}</b></div>`)\n      .join('');\n  } else lp.style.display = 'none';\n\n  $('seedinfo').textContent = `seed: ${runSeed}`;\n}\n\ng.renderPreview = function renderPreview() {\n  const pv = $('previewbox');\n  if (!pv) return;\n  const sel = selectedCards();\n  let handName = '—';\n  let chips = '—', mult = '—', flat = '—', score = '—';\n  let flatOff = true;\n  if (sel.length === 0) {\n    handName = t('pvPick');\n  } else if (sel.some((c) => c.faceDown)) {\n    handName = t('pvFacedown');\n  } else {\n    const r = computeScore(sel, scoreEnv());\n    handName = uiHandName(r.handId, r.core);\n    chips = fmt(r.chips);\n    mult = r.mult;\n    flat = fmt(r.flat);\n    score = fmt(r.score);\n    flatOff = !r.flat;\n  }\n  pv.classList.remove('pv-idle');\n  if (!pv.querySelector('.pv-hand')) {\n    pv.innerHTML = `\n      <div class=\"pv-hand\"></div>\n      <div class=\"pv-boxes\">\n        <div class=\"pv-box chips\"><span class=\"lbl\">${t('pvBase')}</span><span class=\"val\"></span></div>\n        <div class=\"pv-op pv-times\">×</div>\n        <div class=\"pv-box mult\"><span class=\"lbl\">${t('pvMult')}</span><span class=\"val\"></span></div>\n        <div class=\"pv-op\">+</div>\n        <div class=\"pv-box flat\"><span class=\"lbl\">${t('pvFlat')}</span><span class=\"val\"></span></div>\n      </div>\n      <div class=\"pv-total\"><span class=\"tl\">${t('pvTotal')}</span><span class=\"tv\"></span></div>`;\n  }\n  pv.querySelector('.pv-hand').textContent = handName;\n  pv.querySelector('.pv-box.chips .val').textContent = chips;\n  const multBox = pv.querySelector('.pv-box.mult');\n  const multVal = pv.querySelector('.pv-box.mult .val');\n  const timesOp = pv.querySelector('.pv-times');\n  if (sel.length && !sel.some((c) => c.faceDown) && typeof mult === 'number') {\n    applyMultEl(multVal, mult, timesOp);\n    if (multBox) multBox.classList.toggle('is-div', multView(mult).kind !== 'int');\n  } else {\n    if (multVal) multVal.textContent = '—';\n    if (timesOp) { timesOp.textContent = '×'; timesOp.classList.remove('is-div'); }\n    if (multBox) multBox.classList.remove('is-div');\n  }\n  pv.querySelector('.pv-box.flat .val').textContent = flat;\n  pv.querySelector('.pv-box.flat').classList.toggle('off', flatOff);\n  pv.querySelector('.pv-total .tv').textContent = score;\n}\n\ng.renderTable = function renderTable() {\n  const pa = $('playedarea');\n  if (state.juicing) {\n    // playedarea는 juice/discard 시퀀스가 소유 — 손패·버튼만 갱신\n  } else if (state.lastPlay) {\n    // 카드 선택마다 innerHTML을 다시 그리면 점수 애니/깜빡임이 반복되므로 시그니처로 스킵\n    const r = state.lastPlay.result;\n    const sig = `${r.handId}:${r.score}:${state.lastPlay.cards.map((c) => c.uid).join(',')}`;\n    if (pa.dataset.playSig !== sig) {\n      pa.dataset.playSig = sig;\n      pa.classList.remove('juice-stage', 'play-fade-out');\n      pa.innerHTML =\n        state.lastPlay.cards.map((c) => cardHTML(c, { reveal: true })).join('') +\n        `<div id=\"playresult\">\n          <div class=\"r-hand\">${uiHandName(r.handId, r.core)}</div>\n          <div class=\"r-formula\"><span class=\"c\"><span class=\"num\">${fmt(r.chips)}</span>${t('unitChip')}</span> ${multView(r.mult).op === '÷' ? '<span class=\"op-div\">÷</span>' : '×'} <span class=\"m${multView(r.mult).kind !== 'int' ? ' is-div' : ''}\"><span class=\"num\">${fmtMult(r.mult)}</span>${multView(r.mult).kind === 'int' ? t('unitMult') : ''}</span>${r.flat ? ` + <span class=\"num\">${fmt(r.flat)}</span>` : ''}</div>\n          <div class=\"r-score\">+<span class=\"num\">${fmt(r.score)}</span>${t('unitScore')}</div>\n        </div>`;\n    }\n  } else {\n    pa.dataset.playSig = '';\n    pa.classList.remove('juice-stage', 'play-fade-out');\n    pa.innerHTML = `<div class=\"hint\">${t('playHint')}</div>`;\n  }\n\n  const hint = (state.screen === 'play') ? getActiveCoachHint() : null;\n  const auraUids = hint ? new Set(hint.uids) : null;\n  const auraKind = hint && hint.kind === 'junk' ? 'junk' : 'play';\n  renderHandArea({ selectable: true, auraUids, auraKind });\n  requestAnimationFrame(updateBgFigureForHand);\n\n  // 1월 추천 안내\n  let auraHint = $('jan-aura-hint');\n  if (!auraHint) {\n    auraHint = document.createElement('div');\n    auraHint.id = 'jan-aura-hint';\n    $('handarea').parentNode.insertBefore(auraHint, $('handarea'));\n  }\n  if (state.coachStep === 'junk') {\n    auraHint.hidden = false;\n    auraHint.classList.add('junk');\n    auraHint.textContent = t('auraJunkTutor');\n  } else if (hint && hint.kind === 'junk') {\n    auraHint.hidden = false;\n    auraHint.classList.add('junk');\n    auraHint.textContent = t('auraJunk');\n  } else if (hint && hint.kind === 'play') {\n    auraHint.hidden = false;\n    auraHint.classList.remove('junk');\n    auraHint.textContent = hint.handId === 'none'\n      ? t('auraPlayNone')\n      : t('auraPlay')(hint.name);\n  } else {\n    auraHint.hidden = true;\n    auraHint.classList.remove('junk');\n    auraHint.textContent = '';\n  }\n\n  syncHandSortBtn();\n  syncJuiceSpeedBtn();\n  syncPlayActions();\n  if (CHUNHYANG_ENABLED) {\n    $('btn-play').onmouseenter = () => setChunhyangHover('play');\n    $('btn-play').onmouseleave = () => clearChunhyangHover();\n    $('btn-discard').onmouseenter = () => setChunhyangHover('discard');\n    $('btn-discard').onmouseleave = () => clearChunhyangHover();\n    bindActionLongPress($('btn-play'), 'play');\n    bindActionLongPress($('btn-discard'), 'discard');\n  } else {\n    $('btn-play').onmouseenter = null;\n    $('btn-play').onmouseleave = null;\n    $('btn-discard').onmouseenter = null;\n    $('btn-discard').onmouseleave = null;\n  }\n\n}\n\ng.syncPlayActions = function syncPlayActions() {\n  const n = state.selected.length;\n  const canAct = state.screen === 'play' && !state.juicing && !state.dealing;\n  const sortBlocked = !canAct;\n  const handSort = $('hand-sort');\n  if (handSort) {\n    handSort.classList.toggle('sort-blocked', sortBlocked);\n    handSort.querySelectorAll('button').forEach((btn) => { btn.disabled = sortBlocked; });\n  }\n  const playBtn = $('btn-play');\n  const discardBtn = $('btn-discard');\n  if (!playBtn || !discardBtn) return;\n  syncActionBtn(playBtn, t('btnPlay'), state.playsLeft);\n  playBtn.title = t('playTitle')(state.playsLeft);\n  playBtn.disabled = !canAct || n < 1 || n > 5 || state.playsLeft <= 0 || state.coachStep === 'junk';\n  syncActionBtn(discardBtn, t('btnDiscard'), state.discardsLeft);\n  discardBtn.title = t('discardTitle')(state.discardsLeft);\n  discardBtn.disabled = !canAct || n < 1 || n > 5 || state.discardsLeft <= 0;\n}\n\ng.renderCoach = function renderCoach() {\n  const root = $('coach-root');\n  if (!root) return;\n  const step = state.coachStep;\n  const isShop = step === 'shop' || (step && String(step).startsWith('shop'));\n  const isGoStop = step === 'gostop';\n  const ok =\n    step &&\n    ((isShop && state.screen === 'shop') ||\n      (isGoStop && state.screen === 'gostop') ||\n      (!isShop && !isGoStop && state.screen === 'play' && state.round === 1));\n  if (!ok) {\n    root.classList.remove('on');\n    root.setAttribute('aria-hidden', 'true');\n    root.innerHTML = '';\n    return;\n  }\n\n  const aura = (!isShop && !isGoStop) ? getJanAuraBest() : null;\n  const handText = aura\n    ? (aura.handId === 'none'\n      ? tu('coachHandNone')(JAN_AURA_USES)\n      : tu('coachHandNamed')(aura.name, JAN_AURA_USES))\n    : tu('coachHandFallback');\n\n  const playRes = state.lastPlay && state.lastPlay.result;\n  const scoredBody = playRes\n    ? tu('coachScoredBody')(\n        uiHandName(playRes.handId, playRes.core),\n        fmt(playRes.score),\n        fmt(playRes.chips),\n        fmtMultLabel(playRes.mult),\n        playRes.flat ? fmt(playRes.flat) : '',\n        fmt(Math.max(0, state.target - state.roundScore))\n      )\n    : tu('coachScoredFallback');\n\n  const junkHasSel = state.selected.length > 0;\n  const steps = {\n    hand: {\n      sel: '#handarea', pad: 10, title: tu('coachHandTitle'), body: handText, next: null,\n    },\n    play: {\n      sel: '#btn-play', pad: 8, title: tu('coachPlayTitle'),\n      body: tu('coachPlayBody'),\n      next: null,\n    },\n    junk: {\n      sel: junkHasSel ? '#btn-discard' : '#handarea',\n      pad: 8,\n      title: tu('coachJunkTitle'),\n      body: junkHasSel ? tu('coachJunkSel') : tu('coachJunkPick'),\n      next: null,\n    },\n    scored: {\n      sel: '#playedarea', pad: 10, title: tu('coachScoredTitle'),\n      body: scoredBody,\n      next: tu('gotIt'),\n    },\n    gostop: {\n      sel: '#gs-actions', pad: 10, title: tu('coachGoTitle'),\n      body: tu('coachGoBody'),\n      next: null,\n    },\n    shop: {\n      sel: '#shop-offers', pad: 10, title: tu('coachShopTitle'),\n      body: tu('coachShopBody'),\n      next: tu('gotIt'),\n    },\n    deck: {\n      sel: '#deckbox', pad: 8, title: tu('coachDeckTitle'),\n      body: tu('coachDeckBody'),\n      next: null,\n    },\n  };\n  const cfg = steps[step];\n  if (!cfg) {\n    root.classList.remove('on');\n    return;\n  }\n  const target = document.querySelector(cfg.sel);\n  if (!target) {\n    root.classList.remove('on');\n    return;\n  }\n\n  const r = target.getBoundingClientRect();\n  const pad = cfg.pad;\n  const x = Math.max(6, r.left - pad);\n  const y = Math.max(6, r.top - pad);\n  const w = Math.min(window.innerWidth - x - 6, r.width + pad * 2);\n  const h = Math.min(window.innerHeight - y - 6, r.height + pad * 2);\n\n  const spaceBelow = window.innerHeight - (y + h);\n  const panelTop = spaceBelow > 140 ? (y + h + 14) : Math.max(12, y - 130);\n  const panelLeft = Math.min(Math.max(12, x), window.innerWidth - 360);\n\n  const actions = cfg.next\n    ? `<button type=\"button\" class=\"coach-skip\" onclick=\"coachSkip()\">${tu('skip')}</button>\n        <button type=\"button\" class=\"coach-next\" onclick=\"coachNext()\">${cfg.next}</button>`\n    : `<button type=\"button\" class=\"coach-skip\" onclick=\"coachSkip()\">${tu('skip')}</button>`;\n\n  root.classList.add('on');\n  root.setAttribute('aria-hidden', 'false');\n  root.innerHTML = `\n    <div class=\"coach-block\" style=\"left:0;top:0;width:100%;height:${y}px\"></div>\n    <div class=\"coach-block\" style=\"left:0;top:${y + h}px;width:100%;height:${Math.max(0, window.innerHeight - y - h)}px\"></div>\n    <div class=\"coach-block\" style=\"left:0;top:${y}px;width:${x}px;height:${h}px\"></div>\n    <div class=\"coach-block\" style=\"left:${x + w}px;top:${y}px;width:${Math.max(0, window.innerWidth - x - w)}px;height:${h}px\"></div>\n    <div class=\"coach-ring\" style=\"left:${x}px;top:${y}px;width:${w}px;height:${h}px\"></div>\n    <div class=\"coach-panel\" style=\"left:${panelLeft}px;top:${panelTop}px\">\n      <div class=\"coach-title\">${cfg.title}</div>\n      <div>${cfg.body}</div>\n      <div class=\"coach-actions\">${actions}</div>\n    </div>`;\n}\n\ng.renderModal = function renderModal() {\n  const ov = $('modal-overlay');\n  const m = $('modal');\n  const screens = {\n    langpick: langpickHTML,\n    welcome: welcomeHTML, prep: prepHTML, gostop: gostopHTML, nightask: nightaskHTML, settle: settleHTML, shop: shopHTML,\n    gameover: gameoverHTML, victory: victoryHTML, help: helpHTML, deckpeek: deckpeekHTML,\n  };\n  const fn = screens[state.screen];\n  if (!fn) {\n    m.classList.remove('gostop-modal', 'shop-modal', 'dark-shop', 'settle-modal', 'deckpeek-modal', 'howto-modal', 'end-modal', 'prep-modal', 'langpick-modal');\n    m.dataset.modalSig = '';\n    ov.classList.remove('show', 'gostop-open', 'settle-out', 'prep-open');\n    return;\n  }\n\n  if (state.screen === 'nightask') {\n    const sig = `nightask:${state.round}:${state.goLevel}:${state.roundScore}`;\n    m.classList.remove('shop-modal', 'dark-shop', 'settle-modal', 'deckpeek-modal', 'howto-modal', 'end-modal', 'prep-modal');\n    m.classList.add('gostop-modal');\n    ov.classList.remove('settle-out', 'prep-open');\n    ov.classList.add('show', 'gostop-open');\n    if (m.dataset.modalSig === sig) return;\n    m.dataset.modalSig = sig;\n    m.innerHTML = nightaskHTML();\n    return;\n  }\n\n  const isGoStop = state.screen === 'gostop';\n  // 고/스톱은 render가 연달아 두 번 와도 DOM을 다시 안 그림 → 버튼 연출 중복 방지\n  if (isGoStop) {\n    const n = goLevelReached(state.baseTarget, state.roundScore, state.goLevel) + 1;\n    const sig = `gostop:${state.goLevel}:${n}:${state.roundScore}:${state.playsLeft}:${cardsRemaining()}`;\n    m.classList.remove('shop-modal', 'dark-shop', 'settle-modal', 'deckpeek-modal', 'howto-modal', 'end-modal', 'prep-modal');\n    m.classList.add('gostop-modal');\n    ov.classList.remove('settle-out', 'prep-open');\n    ov.classList.add('show', 'gostop-open');\n    if (m.dataset.modalSig === sig) return;\n    m.dataset.modalSig = sig;\n    m.innerHTML = gostopHTML();\n    const stage = $('go-btn-stage');\n    if (stage) {\n      const to = +stage.dataset.to || n;\n      // 버튼 연출은 항상 1→N 전체\n      playGoBtnCascade(0, to);\n    }\n    return;\n  }\n\n  // 정산: 통계 뚱땅뚱 → 팝업 종료 → 주막 등장 (재render 시 연출 중복 방지)\n  if (state.screen === 'settle') {\n    const d = state.settleData;\n    const sig = d\n      ? `settle:${state.round}:${d.total}:${d.moneyBefore}`\n      : `settle:${state.round}`;\n    m.classList.remove('gostop-modal', 'shop-modal', 'dark-shop', 'deckpeek-modal', 'howto-modal', 'end-modal', 'prep-modal');\n    m.classList.add('settle-modal');\n    ov.classList.remove('gostop-open', 'settle-out', 'prep-open');\n    ov.classList.add('show');\n    if (m.dataset.modalSig === sig) return;\n    m.dataset.modalSig = sig;\n    m.innerHTML = settleHTML();\n    playSettleJuice();\n    return;\n  }\n\n  m.dataset.modalSig = state.screen;\n  m.classList.remove('gostop-modal', 'shop-modal', 'dark-shop', 'settle-modal', 'deckpeek-modal', 'howto-modal', 'end-modal', 'prep-modal', 'langpick-modal');\n  if (state.screen === 'shop') {\n    m.classList.add('shop-modal');\n    if (state.darkShop) m.classList.add('dark-shop');\n  } else {\n    m.classList.remove('dark-shop');\n  }\n  if (state.screen === 'prep') m.classList.add('prep-modal');\n  if (state.screen === 'deckpeek') m.classList.add('deckpeek-modal');\n  if (state.screen === 'help' || state.screen === 'welcome') m.classList.add('howto-modal');\n  if (state.screen === 'langpick') m.classList.add('langpick-modal', 'howto-modal');\n  if (state.screen === 'gameover' || state.screen === 'victory') m.classList.add('end-modal');\n  ov.classList.remove('gostop-open', 'settle-out', 'prep-open');\n  if (state.screen === 'prep' || state.screen === 'langpick') ov.classList.add('prep-open');\n  m.innerHTML = fn();\n  ov.classList.add('show');\n  if (state.screen === 'shop') bindOwnedTipAnchors();\n}\n\ng.langpickHTML = function langpickHTML() {\n  return `\n    <h2>십이화 · Sibiwha · 十二花</h2>\n    <div class=\"langpick-sub\">\n      언어를 선택하세요<br>\n      Choose your language<br>\n      言語を選んでください\n    </div>\n    <div class=\"langpick-list\">\n      <button type=\"button\" class=\"langpick-btn\" onclick=\"confirmLocale('kr')\">\n        <span class=\"lp-name\">한국어</span>\n        <span class=\"lp-code\">KR</span>\n      </button>\n      <button type=\"button\" class=\"langpick-btn\" onclick=\"confirmLocale('en')\">\n        <span class=\"lp-name\">English</span>\n        <span class=\"lp-code\">EN</span>\n      </button>\n      <button type=\"button\" class=\"langpick-btn\" onclick=\"confirmLocale('jp')\">\n        <span class=\"lp-name\" style=\"font-family:'Yuji Boku','Hiragino Mincho ProN',serif\">日本語</span>\n        <span class=\"lp-code\">JP</span>\n      </button>\n    </div>`;\n}\n\ng.welcomeHTML = function welcomeHTML() {\n  return `\n    <h2>${tu('welcomeH2')}</h2>\n    <div class=\"sub\" style=\"margin-bottom:10px\">${tu('welcomeSub')}</div>\n    <div class=\"help-sections\">\n      <div class=\"help-card hc-round\">\n        <div class=\"hc-title\">${tu('welcomePlayTitle')}</div>\n        <div class=\"hc-body\">${tu('welcomePlayBody')}</div>\n      </div>\n      <div class=\"help-card hc-time\">\n        <div class=\"hc-title\">${tu('welcomeScoreTitle')}</div>\n        <div class=\"hc-body\">${tu('welcomeScoreBody')}</div>\n      </div>\n      <div class=\"help-card hc-rule\">\n        <div class=\"hc-title\">${tu('welcomeGoTitle')}</div>\n        <div class=\"hc-body\">${tu('welcomeGoBody')}</div>\n      </div>\n      <div class=\"help-card hc-helper\">\n        <div class=\"hc-title\">${tu('welcomeShopTitle')}</div>\n        <div class=\"hc-body\">${tu('welcomeShopBody')}</div>\n      </div>\n    </div>\n    <div class=\"sub help-muted\" style=\"margin-top:12px\">${tu('welcomeFoot')}</div>\n    <div class=\"modal-actions\">\n      <button class=\"choicebtn btn-stop\" style=\"text-align:center\" onclick=\"dismissWelcome()\">\n        <div class=\"t\">${tu('welcomeStart')}</div>\n        <div class=\"d\">${tu('welcomeStartSub')}</div>\n      </button>\n    </div>`;\n}\n\ng.prepHTML = function prepHTML() {\n  const M = MONTHS[0];\n  return `\n    <h2>${tu('prepTitle')(uiMonthName(1))}</h2>\n    <div class=\"sub prep-stats\">${tu('prepTarget')(fmt(TARGETS[0]))}</div>\n    <div class=\"modal-actions\">\n      <button class=\"choicebtn btn-stop prep-start\" onclick=\"beginFromPrep()\">\n        <div class=\"t\">${tu('prepStart')}</div>\n      </button>\n    </div>`;\n}\n\ng.nightaskHTML = function nightaskHTML() {\n  return `\n    <h2>${tu('nightAskH2')}</h2>\n    <div class=\"sub\" style=\"margin-bottom:12px\">${tu('nightAskSub')}</div>\n    <div class=\"modal-actions\">\n      <button class=\"choicebtn btn-stop gs-simple\" onclick=\"declineNight()\">\n        <div class=\"t\">${tu('nightAskNo')}</div>\n        <div class=\"gs-tip\">${tu('nightAskNoTip')}</div>\n      </button>\n      <button class=\"choicebtn btn-go gs-simple\" onclick=\"acceptNight()\">\n        <div class=\"t\">${tu('nightAskYes')}</div>\n        <div class=\"gs-tip\">${tu('nightAskYesTip')}</div>\n      </button>\n    </div>`;\n}\n\ng.gostopHTML = function gostopHTML() {\n  const n = goLevelReached(state.baseTarget, state.roundScore, state.goLevel) + 1;\n  const jump = n - state.goLevel;\n  const newTarget = goThreshold(state.baseTarget, n);\n  const stopTip = state.isNightRound\n    ? (state.goLevel > 0\n      ? tu('gostopStopTipNightN')(state.goLevel, goBonus(state.goLevel, state.round) * 2)\n      : tu('gostopStopTipNight0'))\n    : (state.goLevel > 0\n      ? tu('gostopStopTipN')(state.goLevel, goBonus(state.goLevel, state.round))\n      : tu('gostopStopTip0'));\n  const goTip = (jump > 1 ? tu('gostopJump')(jump) : '')\n    + tu('gostopGoTip')(goBonus(n, state.round));\n  const goTitle = n <= 1\n    ? `<div class=\"t\">${tu('gostopGo1')}</div>`\n    : `<div class=\"t go-btn-stage\" id=\"go-btn-stage\" data-from=\"0\" data-to=\"${n}\"></div>`;\n  const deckLow = state.deck.length > 0 && state.deck.length <= 5;\n  const deckPillCls = `deck-pill gs-deck-peek${deckLow ? ' deck-low' : ''}`;\n  const goJumpHtml = jump > 1\n    ? `<div class=\"gs-go-jump\">${tu('gostopGoJump')(jump)}</div>`\n    : '';\n  const goBtnCls = `choicebtn btn-go gs-simple${jump > 1 ? ' has-jump' : ''}`;\n  return `\n    <div class=\"gs-head-row\">\n      <h2>${tu('gostopH2')}</h2>\n      <button type=\"button\" class=\"${deckPillCls}\" onclick=\"openDeckPeek()\"\n        aria-label=\"${esc(t('deckTitle'))}\">\n        <span class=\"deck-ico\">🂠</span> <b>${state.deck.length}</b>\n      </button>\n    </div>\n    <div class=\"gs-next-target\">\n      <div class=\"gs-next-label\">${tu('gostopNextLabel')(n)}</div>\n      <div class=\"gs-next-score\">${fmt(newTarget)}<span class=\"gs-next-unit\">${tu('scoreUnit')}</span></div>\n    </div>\n    <div class=\"modal-actions\" id=\"gs-actions\">\n      <button class=\"choicebtn btn-stop gs-simple\" onclick=\"chooseStop()\">\n        <div class=\"t\">${tu('gostopStop')}</div>\n        <div class=\"gs-tip\">${stopTip}</div>\n      </button>\n      <button class=\"${goBtnCls}\" onclick=\"chooseGo()\">\n        ${goTitle}\n        ${goJumpHtml}\n        <div class=\"gs-tip\">${goTip}</div>\n      </button>\n    </div>`;\n}\n\ng.settleHTML = function settleHTML() {\n  const d = state.settleData;\n  const rows = [\n    [tu('settleInterest')(d.moneyBefore), d.interest],\n    [tu('settleBase')(isBossRound(state.round)), d.base],\n    [tu('settlePlayBonus')(d.playBonus), d.playBonus],\n  ];\n  if (d.goBonus) rows.push([tu('settleGoBonus')(state.goLevel), d.goBonus]);\n  if (d.insBonus) rows.push([uiJoker(JOKER_BY_ID.pibak_boheom).name, d.insBonus]);\n  return `\n    <h2 class=\"settle-title\">${tu('settleTitle')}</h2>\n    <div class=\"settle-month\">${(state.isNightRound ? tu('settleClearNight') : tu('settleClear'))(state.round, esc(uiMonthName(state.round)))}</div>\n    <div class=\"settle-tally\">\n      <table class=\"settle-table\" id=\"settle-table\">\n        ${rows.map(([k, v]) => `<tr class=\"settle-row\"><td>${k}</td><td><span class=\"settle-amt\">${tu('settleNyang')(v)}</span></td></tr>`).join('')}\n        <tr class=\"total settle-row\"><td>${tu('settleTotal')}</td><td><span class=\"settle-amt\">${tu('settleNyang')(d.total)}</span></td></tr>\n      </table>\n    </div>`;\n}\n\ng.shopHTML = function shopHTML() {\n  const offers = state.shopOffers.map((o, i) => {\n    const j = o.joker;\n    const uj = uiJoker(j);\n    const cant = state.money < j.price || state.jokers.length >= openJokerSlots()\n      || (j.rarity === 'dark' && hasDarkJoker());\n    return `<div class=\"offer aura-${j.rarity}${o.sold ? ' sold' : ''}\">\n      <div class=\"o-icon\">${j.icon}</div>\n      <div class=\"o-name\">${esc(uj.name)}</div>\n      <div class=\"o-meta\">\n        <span class=\"o-rarity r-${j.rarity}\">${uiRarity(j.rarity)}</span>\n        <span class=\"o-kind\">${esc(uj.kind || '')}</span>\n      </div>\n      <div class=\"o-desc\">${esc(uj.desc)}</div>\n      ${o.sold\n        ? `<div class=\"o-sold-tag\">${tu('shopSold')}</div>`\n        : `<button class=\"o-buy\" onclick=\"buyJoker(${i})\" ${cant ? 'disabled' : ''}>${t('nyang')(j.price)}</button>`}\n    </div>`;\n  }).join('');\n\n  const openSlots = openJokerSlots();\n  // 항상 5칸 — 빈/잠긴 칸을 미리 잡아 첫 구매 때 모달이 커지지 않게\n  const ownedSlots = Array.from({ length: JOKER_SLOT_MAX }, (_, i) => {\n    const j = state.jokers[i];\n    if (!j) {\n      if (i >= openSlots) {\n        return `<div class=\"owned-slot locked\" aria-label=\"${esc(lockedSlotLabel(i + 1))}\">\n          <span class=\"os-plus\">＋</span><span>${lockedSlotLabel(i + 1)}</span>\n        </div>`;\n      }\n      return `<div class=\"owned-slot empty\" aria-label=\"빈 특수패 칸\">\n        <span class=\"os-plus\">＋</span><span>${tu('shopEmpty')}</span>\n      </div>`;\n    }\n    const def = JOKER_BY_ID[j.id];\n    const uj = uiJoker(def);\n    const desc = uj.desc + jokerLiveNote(def.id);\n    const gain = formatJokerGain(def.id);\n    const gainShort = formatJokerGain(def.id, { short: true });\n    const gainEmpty = gain === t('gainNone') ? ' empty' : '';\n    const pop = state.shopFlashOwned === i ? ' pop' : '';\n    return `<div class=\"owned-slot filled aura-${def.rarity}${pop}\" onclick=\"toggleOwnedTip(${i}, event)\" title=\"탭하면 설명\">\n      <div class=\"os-tip\">${esc(desc)}<div class=\"os-tip-gain${gainEmpty}\">${esc(gain)}</div></div>\n      <div class=\"os-head\">\n        <div class=\"os-name\">${esc(jokerDisplayName(j))}</div>\n        <div class=\"os-meta\">\n          <span class=\"o-rarity r-${def.rarity}\">${uiRarity(def.rarity)}</span>\n          ${uj.kind ? `<span class=\"o-kind\">${esc(uj.kind)}</span>` : ''}\n        </div>\n      </div>\n      <div class=\"os-desc\">${esc(desc)}</div>\n      <div class=\"os-foot\">\n        <div class=\"os-gain${gainEmpty}\">${esc(gainShort)}</div>\n        <button type=\"button\" class=\"os-sell\" onclick=\"event.stopPropagation(); sellJoker(${i})\">+${t('nyang')(Math.floor(j.paid / 2))}</button>\n      </div>\n    </div>`;\n  }).join('');\n\n  const next = state.round + 1;\n  let bossBlock = '';\n  if (isBossRound(next)) {\n    if (state.bossCandidates && state.bossCandidates.length > 1) {\n      bossBlock = `<div class=\"shop-util su-boss\">\n        <div class=\"su-title\">${tu('shopBossPick')(next)}</div>\n        ${state.bossCandidates.map((id) => {\n          const b = uiBoss(BOSS_BY_ID[id]);\n          return `<button class=\"boss-candidate${state.nextBoss === id ? ' selected' : ''}\" onclick=\"pickBossCandidate('${id}')\">${esc(b.name)} — ${esc(b.desc)}</button>`;\n        }).join('')}\n      </div>`;\n    } else if (state.nextBoss) {\n      const b = uiBoss(BOSS_BY_ID[state.nextBoss]);\n      bossBlock = `<div class=\"shop-util su-boss\">\n        <div class=\"su-title\">${tu('shopBossNext')(next)}</div>\n        <b>${esc(b.name)}</b> — ${esc(b.desc)}\n      </div>`;\n    }\n  }\n\n  const lastMonth = state.round >= ROUNDS;\n  const nextMonth = state.round + 1;\n  const makDisabled = state.chunhyangNext || state.money < 3;\n  const makBlock = CHUNHYANG_ENABLED ? `<div class=\"shop-util su-mak\">\n    <div class=\"su-title\">춘향 훈수 · 3냥</div>\n    ${nextMonth}월 동안 패를 봐주고, 내기/버리기에 올리면 다음 패를 예측해요.\n    <div style=\"margin-top:8px\">\n      <button class=\"smallbtn\" onclick=\"buyChunhyangNext()\" ${makDisabled ? 'disabled' : ''}>${state.chunhyangNext ? '✓ 예약됨' : '다음 달 예약'}</button>\n    </div>\n  </div>` : '';\n\n  const needPick = isBossRound(next) && !state.nextBoss;\n  const nm = MONTHS[next - 1];\n  return `\n    <div class=\"shop-inner\">\n      <div class=\"shop-body\">\n        <div class=\"shop-sign\">\n          <div class=\"shop-titles\">\n            <h2>${state.darkShop ? tu('shopTitleDark') : tu('shopTitle')}</h2>\n            <div class=\"shop-sub\">${(state.darkShop ? tu('shopSubDark') : tu('shopSub'))(state.round)}</div>\n          </div>\n          <div class=\"shop-wallet\"><b>${state.money}냥</b></div>\n        </div>\n        <section class=\"shop-sec\" id=\"shop-owned\">\n          <div class=\"shop-sec-h\">${tu('shopOwned')} <span>${state.jokers.length}/${openSlots}</span></div>\n          <div class=\"shop-owned-slots\">${ownedSlots}</div>\n        </section>\n        <section class=\"shop-sec\" id=\"shop-offers\">\n          <div class=\"shop-sec-h\">\n            ${tu('shopOffers')}\n            <button type=\"button\" class=\"shop-reroll\" onclick=\"reroll()\" ${state.money < state.rerollCost ? 'disabled' : ''}>${tu('shopReroll')(state.rerollCost)}</button>\n          </div>\n          <div class=\"shop-offers\">${offers}</div>\n        </section>\n        ${(makBlock || bossBlock) ? `<section class=\"shop-sec\" id=\"shop-extras\">\n          <div class=\"shop-sec-h\">${tu('shopExtras')}</div>\n          <div class=\"shop-utils\" style=\"${bossBlock ? '' : 'grid-template-columns:1fr'}\">\n            ${makBlock}\n            ${bossBlock}\n          </div>\n        </section>` : ''}\n      </div>\n      <footer class=\"shop-footer\" id=\"shop-footer\">\n        ${lastMonth\n          ? `<div class=\"sf-next\">${tu('shopClearLabel')}\n          <div class=\"sf-target\">${tu('shopClearHint')}</div></div>\n        <button id=\"btn-nextround\" onclick=\"nextRound()\">${tu('shopFinish')}</button>`\n          : `<div class=\"sf-next\">${tu('shopNextLabel')(next, uiMonthName(next))}\n          <div class=\"sf-target\">${tu('shopTarget')(fmt(TARGETS[next - 1]))}</div></div>\n        <button id=\"btn-nextround\" onclick=\"nextRound()\" ${needPick ? `disabled title=\"${tu('shopNeedBoss')}\"` : ''}>${tu('shopNext')}</button>`}\n      </footer>\n    </div>`;\n}\n\ng.gameoverHTML = function gameoverHTML() {\n  return `\n    <h2>${tu('gameoverH2')(esc(uiGameOverReason(state.gameOverReason)))}</h2>\n    <div class=\"sub\">\n      ${tu('gameoverBody')(\n        state.round, ROUNDS, fmt(state.roundScore), fmt(state.target),\n        fmt(state.stats.bestSingle), state.stats.bestSingleHand ? esc(state.stats.bestSingleHand) : '',\n        fmt(state.stats.totalEarned), state.jokers.length\n      )}\n    </div>\n    <div class=\"modal-actions\"><button class=\"choicebtn btn-go\" style=\"text-align:center\" onclick=\"restart()\"><div class=\"t\">${tu('retry')}</div></button></div>`;\n}\n\ng.victoryHTML = function victoryHTML() {\n  return `\n    <h2>${tu('victoryH2')}</h2>\n    <div class=\"sub\">\n      ${tu('victoryBody')(\n        fmt(state.roundScore), fmt(state.target),\n        fmt(state.stats.bestSingle), state.stats.bestSingleHand ? esc(state.stats.bestSingleHand) : '',\n        fmt(state.stats.totalEarned), state.jokers.length\n      )}\n    </div>\n    <div class=\"modal-actions\"><button class=\"choicebtn btn-stop\" style=\"text-align:center\" onclick=\"restart()\"><div class=\"t\">${tu('newRun')}</div></button></div>`;\n}\n\ng.deckpeekHTML = function deckpeekHTML() {\n  const playedUids = new Set((state.playedCards || []).map((c) => c.uid));\n  const discardedUids = new Set((state.discardedCards || []).map((c) => c.uid));\n  const heldUids = new Set((state.hand || []).map((c) => c.uid));\n  const all = [\n    ...state.deck,\n    ...state.hand,\n    ...(state.playedCards || []),\n    ...(state.discardedCards || []),\n  ];\n  const byMonth = {};\n  for (let m = 1; m <= 12; m++) byMonth[m] = [];\n  for (const c of all) byMonth[c.month].push(c);\n  for (let m = 1; m <= 12; m++) {\n    byMonth[m].sort((a, b) => TYPE_ORDER[a.type] - TYPE_ORDER[b.type]);\n  }\n  const rowHTML = (M) => {\n    const cards = byMonth[M.n];\n    const cardsHtml = cards.map((c) => {\n      const inHand = heldUids.has(c.uid);\n      let html = cardHTML(c, { reveal: true, noSeason: true });\n      if (inHand) html = html.replace('class=\"card ', 'class=\"card dp-held ');\n      else if (playedUids.has(c.uid)) html = html.replace('class=\"card ', 'class=\"card dp-played ');\n      else if (discardedUids.has(c.uid)) html = html.replace('class=\"card ', 'class=\"card dp-discarded ');\n      return html;\n    }).join('');\n    return `<div class=\"dp-row\">\n      <div class=\"dp-month\">${hanjaMonth(M.n)}<small>${esc(uiMonthName(M.n))}</small></div>\n      <div class=\"dp-cards\">${cardsHtml}</div>\n    </div>`;\n  };\n  const left = MONTHS.filter((M) => M.n <= 6).map(rowHTML).join('');\n  const right = MONTHS.filter((M) => M.n >= 7).map(rowHTML).join('');\n  const low = state.deck.length > 0 && state.deck.length <= 5;\n  return `\n    <div class=\"modal-head\">\n      <h2 class=\"deck-peek-title\" style=\"margin:0;flex:1;min-width:0\">\n        <span class=\"dp-heading\">${tu('deckPeekTitle')}</span>\n        <span class=\"deck-peek-count${low ? ' deck-low' : ''}\">${tu('deckLeft')(state.deck.length)}</span>\n      </h2>\n      <button type=\"button\" class=\"modal-close\" onclick=\"closeDeckPeek()\" aria-label=\"${tu('close')}\">×</button>\n    </div>\n    <div class=\"deck-peek-cols\">\n      <div class=\"deck-peek-col\">${left}</div>\n      <div class=\"deck-peek-col\">${right}</div>\n    </div>\n    <div class=\"modal-actions\">\n      <button class=\"choicebtn btn-stop\" style=\"text-align:center\" onclick=\"closeDeckPeek()\">\n        <div class=\"t\">${tu('close')}</div>\n      </button>\n    </div>`;\n}\n\ng.helpHTML = function helpHTML() {\n  // 족보를 대표하는 실제 카드 — 이모지 대신 이미 있는 카드 아트를 쓴다\n  const HAND_VIS = {\n    ogwang:     'Assets/01_january/1-gwang.webp',\n    sagwang:    'Assets/03_march/3-gwang.webp',\n    chongtong:  'Assets/11_november/11-gwang.webp',\n    godori:     'Assets/02_february/2-yeolkkeut-warbler.webp',\n    bigodori:   'Assets/12_december/12-yeolkkeut-swallow.webp',\n    samgwang:   'Assets/08_august/8-gwang.webp',\n    bisamgwang: 'Assets/12_december/12-gwang-umbrella.webp',\n    dan:        'Assets/01_january/1-tti-hongdan.webp',\n    byeongpung: 'Assets/05_may/5-yeolkkeut.webp',\n    month3:     'Assets/07_july/7-yeolkkeut.webp',\n    yeol3:      'Assets/06_june/6-yeolkkeut.webp',\n    tti3:       'Assets/06_june/6-tti-cheongdan.webp',\n    pi5:        'Assets/12_december/12-pi-ssangpi.webp',\n    month2:     'Assets/03_march/3-pi-1.webp',\n  };\n  const rows = HANDS.map((h, i) => {\n    const tier = h.id === 'bisamgwang' ? 'bi'\n      : i <= 1 ? 's' : i <= 5 ? 'a' : i <= 8 ? 'b' : i <= 12 ? 'c' : 'd';\n    return `<div class=\"hb-row t-${tier}\">\n      <div class=\"hb-rank\">${i + 1}</div>\n      <div class=\"hb-vis\" aria-hidden=\"true\">${HAND_VIS[h.id]\n        ? `<img src=\"${esc(assetSrc(HAND_VIS[h.id]))}\" alt=\"\" draggable=\"false\">` : ''}</div>\n      <div>\n        <div class=\"hb-name\">${uiHandName(h.id)}</div>\n        <div class=\"hb-cond\">${uiHandCond(h.id)}</div>\n      </div>\n      <div class=\"hb-mult\">×${h.mult}</div>\n    </div>`;\n  }).join('');\n  const tags = (tu('helpJokerTags') || []).map((s) => `<span>${s}</span>`).join('');\n  return `\n    <div class=\"modal-head\">\n      <h2>${tu('helpH2')}</h2>\n      <button type=\"button\" class=\"modal-close\" onclick=\"closeHelp()\" aria-label=\"${tu('close')}\">×</button>\n    </div>\n    <div class=\"sub\" style=\"margin-bottom:6px\">${tu('helpIntro')}</div>\n    <div class=\"handbook-legend\">\n      <span class=\"lg\"><span class=\"dot\" style=\"background:var(--tier-s)\"></span>${tu('legendS')}</span>\n      <span class=\"lg\"><span class=\"dot\" style=\"background:var(--tier-a)\"></span>${tu('legendA')}</span>\n      <span class=\"lg\"><span class=\"dot\" style=\"background:var(--tier-b)\"></span>${tu('legendB')}</span>\n      <span class=\"lg\"><span class=\"dot\" style=\"background:var(--tier-c)\"></span>${tu('legendC')}</span>\n      <span class=\"lg\"><span class=\"dot\" style=\"background:var(--tier-d)\"></span>${tu('legendD')}</span>\n    </div>\n    <div class=\"handbook\">${rows}</div>\n    <div class=\"chip-legend\">\n      <span>${tu('chipKwang')} 12</span><span>${tu('chipYeol')} 8</span><span>${tu('chipTti')} 6</span>\n      <span>${tu('chipSsang')} 5</span><span>${tu('chipPi')} 2</span>\n    </div>\n    <div class=\"help-sections\">\n      <div class=\"help-card hc-time\">\n        <div class=\"hc-title\">${tu('helpTimeTitle')}</div>\n        <div class=\"hc-body\">${tu('helpTimeBody')(uiMonthName(1), uiMonthName(12))}</div>\n        <div class=\"help-tags\">\n          <span>${tu('helpTimeDay')}</span>\n          <span>${tu('helpTimeNight')}</span>\n        </div>\n      </div>\n      <div class=\"help-card hc-round\">\n        <div class=\"hc-title\">${tu('helpRoundTitle')}</div>\n        <div class=\"hc-body\">${tu('helpRoundBody')}</div>\n      </div>\n      <div class=\"help-card hc-rule\">\n        <div class=\"hc-title\">${tu('helpRuleTitle')}</div>\n        <div class=\"hc-body\">${tu('helpRuleBody')}</div>\n        <div class=\"help-tags\"><span>${tu('helpRuleTag')}</span></div>\n      </div>\n      <div class=\"help-card hc-helper\">\n        <div class=\"hc-title\">${tu('helpJokerTitle')}</div>\n        <div class=\"hc-body\">${tu('helpJokerBody')}</div>\n        <div class=\"help-tags\">${tags}</div>\n      </div>\n    </div>\n    <div class=\"modal-actions\"><button class=\"choicebtn btn-stop\" style=\"text-align:center\" onclick=\"closeHelp()\"><div class=\"t\">${tu('close')}</div></button></div>`;\n}\n\ng.flashActions = function flashActions() {\n  const el = $('actions');\n  el.classList.remove('shake');\n  void el.offsetWidth;\n  el.classList.add('shake');\n}\n\n/* ================================================================\n   주스 연출 (오버레이 — state 중간값 오염 금지, lastPlay 스냅샷만 재생)\n   ================================================================ */\ng.JUICE = {\n  skip: false,\n  running: false,\n  onSkip: null,\n};\n\n/** 점수 연출 템포 — 1보다 크면 느리게. juiceSpeed(1|2)로 배속 */\ng.JUICE_TEMPO = 1.08;\ng.juiceMs = function juiceMs(ms) { return Math.max(1, Math.round(ms * JUICE_TEMPO / juiceSpeed)); }\ng.juiceWait = function juiceWait(ms) {\n  return new Promise((resolve) => {\n    if (JUICE.skip) { resolve(); return; }\n    const t = setTimeout(resolve, juiceMs(ms));\n    const prev = JUICE.onSkip;\n    JUICE.onSkip = () => { clearTimeout(t); prev && prev(); resolve(); };\n  });\n}\n\ng.juiceTier = function juiceTier(handId) {\n  const i = HANDS.findIndex((h) => h.id === handId);\n  if (i <= 1) return 'S';\n  if (i <= 5) return 'A';\n  if (i <= 9) return 'B';\n  if (i <= 13) return 'C';\n  return 'D';\n}\n\n/** 특수패 슬롯 효과 발동 연출 — 살짝 뽀용 */\ng.pulseJokerSlots = function pulseJokerSlots(ids) {\n  if (!ids?.length) return;\n  const want = new Set(ids);\n  document.querySelectorAll('#jokerbar .jokerslot.filled[data-jid]').forEach((el) => {\n    if (!want.has(el.dataset.jid)) return;\n    el.classList.remove('trig');\n    void el.offsetWidth;\n    el.classList.add('trig');\n    const clear = () => el.classList.remove('trig');\n    el.addEventListener('animationend', clear, { once: true });\n    setTimeout(clear, 480);\n  });\n}\n\n/** 특수패가 건드리는 카드들 (연출용) */\ng.jokerAffectedCards = function jokerAffectedCards(id, ctx) {\n  const cards = ctx.cards || [];\n  const core = ctx.core || [];\n  switch (id) {\n    case 'gwangpari':\n    case 'gwang_sujip':\n      return cards.filter((c) => c.type === 'kwang');\n    case 'samgwang_nori':\n      return core.filter((c) => c.type === 'kwang');\n    case 'pi_merchant':\n      return cards.filter((c) => { const t = effType(c); return t === 'pi' || t === 'ssangpi'; });\n    case 'meongtta':\n      return cards.filter((c) => effType(c) === 'yeol');\n    case 'jjokjipge':\n      return ctx.handId === 'month2' ? core : [];\n    case 'ssangpi_sarang':\n      return cards.filter((c) => effType(c) === 'ssangpi');\n    case 'tti_jjang':\n      return cards.filter((c) => effType(c) === 'tti');\n    case 'ssakssuri':\n      return cards.length === 5 ? cards : [];\n    case 'godori_kkun':\n      return core.filter((c) => c.tags.includes('godori'));\n    case 'dangol':\n      return (ctx.handId === 'dan' || ctx.handId === 'tti3') ? core : [];\n    case 'heundeulgi': {\n      if (ctx.boss === 'no_shake') return [];\n      const cnt = {};\n      for (const c of cards) cnt[c.month] = (cnt[c.month] || 0) + 1;\n      return cards.filter((c) => cnt[c.month] >= 2);\n    }\n    case 'pi_ohjang':\n      return ctx.handId === 'pi5' ? cards.filter((c) => piCount(c) > 0) : [];\n    case 'chodan_aeho':\n      return core.filter((c) => c.tags.includes('chodan'));\n    case 'bigwang_usan':\n      return ctx.handId === 'none' ? [] : core.filter((c) => c.month === 12);\n    case 'poktan':\n      return (ctx.handId === 'month3' || ctx.handId === 'chongtong') ? core : [];\n    case 'yeol_janchi':\n      return ctx.handId === 'yeol3' ? cards.filter((c) => effType(c) === 'yeol') : [];\n    case 'sipidal':\n      return cards;\n    case 'ogwang_kkum': {\n      const kw = cards.filter((c) => c.type === 'kwang');\n      return kw.length >= 3 ? kw : [];\n    }\n    case 'paewang':\n      return ctx.handId !== 'none' ? core : [];\n    case 'matdae':\n      return matdaeCards(cards);\n    default:\n      return [];\n  }\n}\n\n/** 카드 한 장마다 세는 특수패 — 정산도 한 장씩 */\ng.jokerJuiceEach = function jokerJuiceEach(id) {\n  return [\n    'gwangpari', 'pi_merchant', 'meongtta', 'ssangpi_sarang', 'tti_jjang',\n    'godori_kkun', 'gwang_sujip', 'chodan_aeho', 'samgwang_nori',\n  ].includes(id);\n}\n\n/** 카드 위 특수패 칩 라벨 (+4, +1냥 등) */\ng.jokerCardFx = function jokerCardFx(id, card) {\n  if (id === 'gwangpari') return { label: '+1냥', money: 1 };\n  if (id === 'pi_merchant') {\n    const ss = effType(card) === 'ssangpi';\n    return { label: ss ? '+8' : '+4', chip: ss ? 8 : 4 };\n  }\n  if (id === 'meongtta') return { label: '+6', chip: 6 };\n  if (id === 'ssangpi_sarang') return { label: '+12', chip: 12 };\n  if (id === 'tti_jjang') return { label: '+5', chip: 5 };\n  if (id === 'gwang_sujip') return { label: '+10', chip: 10 };\n  if (id === 'godori_kkun') return { label: '+3', addMult: 3 };\n  if (id === 'chodan_aeho') return { label: '+2', addMult: 2 };\n  if (id === 'samgwang_nori') return { label: '+3', addMult: 3 };\n  return { label: null };\n}\n\ng.jokerCardLabel = function jokerCardLabel(id, card) {\n  return jokerCardFx(id, card).label;\n}\n\ng.parseJokerChipLabel = function parseJokerChipLabel(label) {\n  if (!label || label.includes('냥')) return 0;\n  const m = String(label).match(/^\\+(\\d+)/);\n  return m ? parseInt(m[1], 10) : 0;\n}\n\n/** 아이템 정산 시 관련 카드 펄스. 호출 측이 한 장만 넘기면 한 장씩, 여러 장이면 한 번에. */\ng.pulseJuiceCardsForJoker = async function pulseJuiceCardsForJoker(wraps, cardSteps, affected, { labelsByUid = {}, rarity = 'common' } = {}) {\n  if (!affected?.length || !wraps?.length) return;\n  const uids = new Set(affected.map((c) => c.uid));\n  const hitR = `hit-${rarity}`;\n  let any = false;\n  for (let i = 0; i < cardSteps.length; i++) {\n    if (JUICE.skip) break;\n    if (!uids.has(cardSteps[i].card.uid)) continue;\n    const w = wraps[i];\n    if (!w) continue;\n    w.classList.remove('pulse', 'joker-hit', 'hit-common', 'hit-rare', 'hit-epic', 'hit-legendary');\n    void w.offsetWidth;\n    w.classList.add('joker-hit', hitR);\n    w.querySelectorAll('.chip-float.joker-fx').forEach((el) => el.remove());\n    const labels = labelsByUid[cardSteps[i].card.uid] || [];\n    labels.forEach((lab, idx) => {\n      const fx = document.createElement('div');\n      fx.className = `chip-float joker-fx ${hitR}`;\n      fx.textContent = lab;\n      if (labels.length > 1) fx.style.top = `${-8 - idx * 24}px`;\n      w.appendChild(fx);\n      void fx.offsetWidth;\n      fx.classList.add('go');\n    });\n    any = true;\n  }\n  if (any) sfxChip();\n  await juiceWait(280);\n  for (const w of wraps) {\n    w.classList.remove('joker-hit', 'hit-common', 'hit-rare', 'hit-epic', 'hit-legendary');\n  }\n}\n\n/** 연기된 특수패 경제·이득 반영 (미지급분만, 스킵/리듀스/finally 공용) */\ng.applyJokerEconomy = function applyJokerEconomy(snap) {\n  if (!snap || snap._econApplied) return;\n  snap._econApplied = true;\n  const n = snap.pendingGwangpari || 0;\n  const paid = snap._gwangpariPaid || 0;\n  const left = Math.max(0, n - paid);\n  if (left > 0) {\n    addMoney(left);\n    state.kwangSoldThisRound += left;\n    bumpJokerGain('gwangpari', { money: left });\n    snap._gwangpariPaid = n;\n    snap._moneyPaid = true;\n  }\n  const bumped = snap._scoreBumped || new Set();\n  for (const ef of snap.jokerScoreGains || []) {\n    if (ef.score && !bumped.has(ef.id)) {\n      bumpJokerGain(ef.id, { score: ef.score });\n      bumped.add(ef.id);\n    }\n  }\n  snap._scoreBumped = bumped;\n  const mb = $('moneybox');\n  if (mb) mb.textContent = `${state.money}냥`;\n}\n\ng.juiceBreakdown = function juiceBreakdown(snap) {\n  const { cards, result, env } = snap;\n  let handId = result.handId;\n  // lastPlay.cards는 스냅샷 복사본, result.core는 원본 참조 → uid로 다시 붙인다\n  const coreUids = new Set((result.core || []).map((c) => c.uid));\n  let core = cards.filter((c) => coreUids.has(c.uid));\n  if (!core.length) core = [...cards];\n  if (env.boss === 'no_shake' && ['month2', 'month3', 'chongtong'].includes(handId)) {\n    handId = 'none';\n    core = [...cards];\n  }\n  const coreSet = new Set(core);\n  const steps = cards.map((c) => ({\n    card: c,\n    chip: cardChip(c, env),\n    isCore: coreSet.has(c),\n  }));\n  const cardFlat = steps.filter((s) => !s.isCore).reduce((a, s) => a + s.chip, 0);\n  const jokerChips = Math.max(0, result.flat - cardFlat);\n  let baseMult = HAND_BY_ID[result.handId]?.mult ?? 1;\n  if ((env.jokerIds || []).includes('geokkuro')) baseMult = 1 / baseMult;\n  const ctx = scoreJokerCtx(cards, result.handId, core, env);\n  // 특수패 슬롯 왼쪽→오른쪽 · 발동분만 — 칩 → +배수 → ×배수 → 냥\n  const orderOf = (c) => cards.findIndex((x) => x.uid === c.uid);\n  const jokerSteps = [];\n  for (const id of env.jokerIds) {\n    const j = JOKER_BY_ID[id];\n    if (!j) continue;\n    const chipGain = j.addChips ? j.addChips(ctx) : 0;\n    const addM = j.addMult ? j.addMult(ctx) : 0;\n    const xm = j.xMult ? j.xMult(ctx) : 1;\n    const money = id === 'gwangpari' ? (snap.pendingGwangpari || 0) : 0;\n    if (chipGain || addM || xm !== 1 || money) {\n      let affected = jokerAffectedCards(id, ctx)\n        .slice()\n        .sort((a, b) => orderOf(a) - orderOf(b));\n      if (id === 'gwangpari' && money > 0) affected = affected.slice(0, money);\n      jokerSteps.push({\n        id, chipGain, addMult: addM, xMult: xm, money, affected,\n      });\n    }\n  }\n  return {\n    handBase: 0, steps, jokerChips, jokerSteps, baseMult, ctx,\n    flatSum: result.flat, cardFlat, mult: result.mult, score: result.score,\n    handId: result.handId, core,\n  };\n}\n\n";
new Function('g', 'with (g) {\n' + code + '\n}')(g);
